ddl:
CREATE TABLE cliente (
    id int PRIMARY KEY,
    nome varchar(100) not null,
    email varchar(150) unique
);

CREATE TABLE pedido (
    id int PRIMARY KEY,
    cliente_id int not null REFERENCES cliente (id),
    valor decimal(10,2)
);
